/// Follows what run `run` of the project on hand, of `agent`, reports
/// of its usage.
fn follow_usage(
    &mut self,
    run: Option<usize>,
    agent: crate::agent::Agent,
    event: &HarnessEvent,
) {
    let now = usage::now();
    if let Some(run) = run {
        self.usage.follow(run, agent, event, now);
    }
    self.limits.follow(agent, event, now);
}

